#!/usr/bin/env python3
"""Generate the native cache-contract-v3 schema constants header."""
from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path


def _quoted(values: list[str]) -> str:
    return ",\n\t".join(f'TEXT("{value}")' for value in values)


def generate(schema_path: Path) -> bytes:
    try:
        raw = schema_path.read_bytes()
        schema = json.loads(raw.decode("utf-8"))
        definitions = schema["$defs"]
        payload_properties = definitions["payload"]["properties"]
        format_name = payload_properties["format"]["const"]
        contract_version = payload_properties["contract_version"]["const"]
        generic_importer = schema["x-wot-contract"]["generic_importer"]
        domains = definitions["fact"]["properties"]["domain"]["enum"]
        envelope_fields = schema["required"]
        payload_fields = definitions["payload"]["required"]
        fact_fields = definitions["fact"]["required"]
        source_fields = definitions["source"]["required"]
        output_fields = definitions["output"]["required"]
        audit_fields = definitions["audit"]["required"]
        if (not isinstance(format_name, str) or not format_name
                or isinstance(contract_version, bool)
                or not isinstance(contract_version, int)
                or contract_version < 0
                or not isinstance(generic_importer, str) or not generic_importer
                or not isinstance(domains, list)
                or not all(isinstance(domain, str) and domain for domain in domains)):
            raise TypeError("schema contract constants have invalid types")
    except (OSError, UnicodeError, json.JSONDecodeError, KeyError, TypeError) as exc:
        raise ValueError(f"cannot read cache-v3 schema {schema_path}: {exc}") from exc
    digest = hashlib.sha256(raw).hexdigest()
    lines = [
        "// Generated by Tools/dist/generate_cache_contract_header.py; do not edit.",
        "#pragma once", "", "#include \"CoreMinimal.h\"", "",
        "namespace WoT::Retail::Generated", "{",
        f'inline constexpr TCHAR SchemaSha256[] = TEXT("{digest}");',
        f'inline constexpr TCHAR Format[] = TEXT("{format_name}");',
        f'inline constexpr TCHAR GenericImporter[] = TEXT("{generic_importer}");',
        f"inline constexpr uint32 ContractVersion = {contract_version};", "",
    ]
    for name, values in (
        ("EnvelopeFields", envelope_fields), ("PayloadFields", payload_fields),
        ("FactFields", fact_fields), ("SourceFields", source_fields),
        ("OutputFields", output_fields), ("AuditFields", audit_fields),
        ("DomainNames", domains),
    ):
        ordered_values = values if name == "DomainNames" else sorted(values)
        lines.extend((f"inline constexpr const TCHAR* {name}[] = {{",
                      f"\t{_quoted(ordered_values)}", "};", ""))
    lines.extend(("}  // namespace WoT::Retail::Generated", ""))
    return "\n".join(lines).encode("utf-8")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--schema", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    try:
        expected = generate(args.schema)
        if args.check:
            actual = args.output.read_bytes()
            if actual != expected:
                print(f"cache contract generated header is stale: {args.output}",
                      file=sys.stderr)
                return 1
        else:
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_bytes(expected)
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    print(f"cache contract header OK: {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
